import React, { useState, useEffect, useRef, useCallback } from 'react';
import { VideoOff, Clock, Volume2, Mic, CheckCircle, AlertCircle } from 'lucide-react';

// Safe imports with fallbacks
let VoiceEngine;
let SpeechSynthesisEngine;
let generateInterviewQuestions;
let scoreAnswerWithAI;

try {
  VoiceEngine = require('../ai/VoiceEngine').VoiceEngine;
} catch (error) {
  console.warn('VoiceEngine not available, using fallback');
  VoiceEngine = class {
    start() { 
      console.log('VoiceEngine fallback: start');
      return false; 
    }
    stop() { 
      console.log('VoiceEngine fallback: stop');
      return ''; 
    }
    abort() { console.log('VoiceEngine fallback: abort'); }
    setCallbacks() { console.log('VoiceEngine fallback: setCallbacks'); }
    isActive() { return false; }
  };
}

try {
  SpeechSynthesisEngine = require('../ai/SpeechSynthesis').SpeechSynthesisEngine;
} catch (error) {
  console.warn('SpeechSynthesisEngine not available, using fallback');
  SpeechSynthesisEngine = class {
    async initialize() { 
      console.log('SpeechSynthesisEngine fallback: initialize');
      return true;
    }
    async speak(text, options) { 
      console.log('SpeechSynthesisEngine fallback: speak', text);
      if (options?.onEnd) {
        setTimeout(options.onEnd, 1000);
      }
    }
    stop() { console.log('SpeechSynthesisEngine fallback: stop'); }
  };
}

try {
  const geminiAI = require('../ai/GeminiAI');
  generateInterviewQuestions = geminiAI.generateRealisticInterviewQuestions;
  scoreAnswerWithAI = geminiAI.scoreAnswerWithAI;
} catch (error) {
  console.warn('GeminiAI not available, using fallbacks');
  generateInterviewQuestions = async (resumeText, jobRole) => {
    console.log('generateInterviewQuestions - Analyzing resume for ANY industry role...');

    // Parse resume to extract key information
    const resumeLower = (resumeText || '').toLowerCase();

    // Comprehensive skill detection for ALL industries
    const detectedSkills = [];
    const allSkills = {
      // Technology & Software
      'React': ['react', 'reactjs', 'react.js', 'react native'],
      'Angular': ['angular', 'angularjs'],
      'Vue': ['vue', 'vuejs', 'vue.js'],
      'Node.js': ['node', 'nodejs', 'node.js', 'express'],
      'Python': ['python', 'django', 'flask', 'fastapi'],
      'Java': ['java', 'spring', 'springboot', 'hibernate'],
      'JavaScript': ['javascript', 'js', 'typescript'],
      '.NET': ['.net', 'c#', 'asp.net'],
      'PHP': ['php', 'laravel', 'symfony'],
      'Ruby': ['ruby', 'rails', 'ruby on rails'],

      // Enterprise Software
      'SAP': ['sap', 'abap', 'fiori', 's/4hana', 'sap hana', 'sap mm', 'sap sd'],
      'Salesforce': ['salesforce', 'apex', 'lightning', 'crm'],
      'Oracle': ['oracle', 'pl/sql', 'oracle database'],
      'ServiceNow': ['servicenow', 'itsm'],
      'Workday': ['workday', 'hcm'],

      // Cloud & DevOps
      'AWS': ['aws', 'amazon web services', 'ec2', 's3', 'lambda'],
      'Azure': ['azure', 'microsoft azure'],
      'Google Cloud': ['gcp', 'google cloud', 'cloud platform'],
      'Docker': ['docker', 'kubernetes', 'k8s', 'containerization'],
      'DevOps': ['devops', 'ci/cd', 'jenkins', 'gitlab', 'terraform'],

      // Data & Analytics
      'Data Analysis': ['data analysis', 'analytics', 'data visualization', 'tableau', 'power bi'],
      'Machine Learning': ['machine learning', 'ml', 'ai', 'tensorflow', 'pytorch'],
      'Data Science': ['data science', 'pandas', 'numpy', 'scikit-learn'],
      'SQL': ['sql', 'mysql', 'postgresql', 'database', 'data warehouse'],
      'Big Data': ['hadoop', 'spark', 'hive', 'big data'],

      // Design
      'UI/UX Design': ['ui', 'ux', 'user interface', 'user experience', 'figma', 'sketch', 'adobe xd'],
      'Graphic Design': ['graphic design', 'photoshop', 'illustrator', 'indesign'],
      'Product Design': ['product design', 'prototyping', 'wireframing'],

      // Marketing & Sales
      'Digital Marketing': ['digital marketing', 'seo', 'sem', 'google ads', 'social media marketing'],
      'Content Marketing': ['content marketing', 'content creation', 'copywriting'],
      'Email Marketing': ['email marketing', 'mailchimp', 'hubspot'],
      'Sales': ['sales', 'business development', 'lead generation', 'crm'],
      'Social Media': ['social media', 'facebook', 'instagram', 'linkedin', 'twitter'],

      // Finance & Accounting
      'Accounting': ['accounting', 'bookkeeping', 'accounts payable', 'accounts receivable'],
      'Financial Analysis': ['financial analysis', 'financial modeling', 'excel', 'forecasting'],
      'Investment Banking': ['investment banking', 'equity research', 'valuation'],
      'Taxation': ['taxation', 'tax preparation', 'gst', 'income tax'],
      'Auditing': ['auditing', 'internal audit', 'compliance'],

      // HR & Recruitment
      'Human Resources': ['human resources', 'hr', 'recruitment', 'talent acquisition'],
      'Payroll': ['payroll', 'compensation', 'benefits'],
      'Employee Relations': ['employee relations', 'performance management'],

      // Operations & Supply Chain
      'Supply Chain': ['supply chain', 'logistics', 'inventory management'],
      'Operations Management': ['operations', 'process improvement', 'lean', 'six sigma'],
      'Project Management': ['project management', 'pmp', 'agile', 'scrum', 'jira'],
      'Quality Assurance': ['quality assurance', 'qa', 'testing', 'quality control'],

      // Healthcare
      'Nursing': ['nursing', 'rn', 'patient care', 'clinical'],
      'Medical': ['medical', 'physician', 'doctor', 'healthcare'],
      'Pharmacy': ['pharmacy', 'pharmacist', 'pharmaceutical'],

      // Legal
      'Legal': ['legal', 'law', 'attorney', 'paralegal', 'litigation'],
      'Contract Management': ['contract', 'agreement', 'legal compliance'],

      // Education
      'Teaching': ['teaching', 'teacher', 'education', 'curriculum', 'instructor'],
      'Training': ['training', 'corporate training', 'e-learning', 'instructional design'],

      // Customer Service
      'Customer Support': ['customer support', 'customer service', 'help desk', 'technical support'],
      'Call Center': ['call center', 'bpo', 'contact center'],

      // Management
      'Leadership': ['leadership', 'team management', 'people management'],
      'Strategy': ['strategy', 'strategic planning', 'business strategy'],
      'Consulting': ['consulting', 'advisory', 'business consulting'],

      // Other Professional Skills
      'Content Writing': ['content writing', 'technical writing', 'blogging'],
      'Research': ['research', 'market research', 'academic research'],
      'Engineering': ['engineering', 'mechanical', 'electrical', 'civil'],
      'Architecture': ['architecture', 'architectural design', 'cad', 'autocad']
    };

    for (const [skill, keywords] of Object.entries(allSkills)) {
      if (keywords.some(kw => resumeLower.includes(kw))) {
        detectedSkills.push(skill);
      }
    }

    // Detect experience level
    let experienceLevel = 'fresher';
    let yearsExp = 0;
    if (resumeLower.includes('years') || resumeLower.includes('experience')) {
      const yearMatch = resumeLower.match(/(\d+)\s*(?:\+)?\s*years?/);
      if (yearMatch) {
        yearsExp = parseInt(yearMatch[1]);
        if (yearsExp >= 7) experienceLevel = 'senior';
        else if (yearsExp >= 3) experienceLevel = 'mid';
        else if (yearsExp >= 1) experienceLevel = 'junior';
      }
    }

    // Smart role detection from resume content
    let detectedRole = jobRole;

    if (!detectedRole || detectedRole === 'Full Stack Developer') {
      // Try to detect role from skills and keywords
      if (detectedSkills.includes('SAP')) detectedRole = 'SAP Consultant';
      else if (detectedSkills.includes('Salesforce')) detectedRole = 'Salesforce Developer';
      else if (detectedSkills.includes('Data Science') || detectedSkills.includes('Machine Learning')) detectedRole = 'Data Scientist';
      else if (detectedSkills.includes('Data Analysis')) detectedRole = 'Data Analyst';
      else if (detectedSkills.includes('DevOps')) detectedRole = 'DevOps Engineer';
      else if (detectedSkills.includes('UI/UX Design')) detectedRole = 'UI/UX Designer';
      else if (detectedSkills.includes('Digital Marketing')) detectedRole = 'Digital Marketing Specialist';
      else if (detectedSkills.includes('Human Resources')) detectedRole = 'HR Professional';
      else if (detectedSkills.includes('Accounting')) detectedRole = 'Accountant';
      else if (detectedSkills.includes('Sales')) detectedRole = 'Sales Professional';
      else if (detectedSkills.includes('Project Management')) detectedRole = 'Project Manager';
      else if (detectedSkills.includes('Nursing')) detectedRole = 'Nurse';
      else if (detectedSkills.includes('Teaching')) detectedRole = 'Teacher';
      else if (detectedSkills.includes('Legal')) detectedRole = 'Legal Professional';
      else if (detectedSkills.includes('Customer Support')) detectedRole = 'Customer Support Specialist';
      else if (detectedSkills.includes('Content Writing')) detectedRole = 'Content Writer';
      else if (detectedSkills.includes('React') || detectedSkills.includes('Angular') || detectedSkills.includes('Vue')) detectedRole = 'Frontend Developer';
      else if (detectedSkills.includes('Node.js') || detectedSkills.includes('Python') || detectedSkills.includes('Java')) detectedRole = 'Backend Developer';
      else detectedRole = 'Professional';
    }

    console.log('🔍 Detected Skills:', detectedSkills.slice(0, 5));
    console.log('📊 Experience Level:', experienceLevel, `(${yearsExp} years)`);
    console.log('💼 Detected Role:', detectedRole);

    // Generate highly personalized questions
    const questions = [];
    let qId = 1;

    // 1. INTRODUCTION - Always personalized to role
    questions.push({
      id: qId++,
      question: `Tell me about yourself and your professional background in ${detectedRole}.`,
      difficulty: 'Easy',
      time: 120,
      type: 'introduction'
    });

    // 2-4. ROLE-SPECIFIC TECHNICAL QUESTIONS (Based on detected skills) - INCREASED FROM 2 TO 3
    const primarySkill = detectedSkills[0];
    const secondarySkill = detectedSkills[1];
    const tertiarySkill = detectedSkills[2];

    if (primarySkill) {
      // Technical question 1 - Deep dive into primary skill
      const techQuestions = {
        'SAP': 'What SAP modules have you worked with? Describe a complex business process you configured in SAP and the challenges you faced.',
        'Salesforce': 'Explain your experience with Apex and Lightning components. Can you describe a complex automation or integration you built in Salesforce?',
        'React': 'Explain how you manage state in React applications. Discuss performance optimization techniques you have used in production.',
        'Python': 'What Python frameworks and libraries have you used? Describe a challenging algorithmic or data processing problem you solved.',
        'Data Science': 'Walk me through your approach to building a machine learning model. What techniques do you use for feature engineering and model evaluation?',
        'Data Analysis': 'Describe your process for analyzing large datasets. What statistical methods and visualization techniques do you use regularly?',
        'Digital Marketing': 'Explain your approach to running paid advertising campaigns. How do you optimize for ROI and measure campaign success?',
        'UI/UX Design': 'Walk me through your design process from user research to final design. How do you validate design decisions with data?',
        'Human Resources': 'Describe your end-to-end recruitment process. How do you source candidates, conduct interviews, and ensure cultural fit?',
        'Accounting': 'Explain your experience with month-end closing processes. How do you ensure accuracy in financial reporting and handle reconciliations?',
        'Project Management': 'Describe how you manage project scope, timeline, and budget. What tools and methodologies do you use for risk management?',
        'Sales': 'Walk me through your sales cycle from prospecting to closing. How do you handle objections and negotiate deals?',
        'Nursing': 'Describe your approach to patient assessment and care planning. How do you prioritize tasks during a busy shift?',
        'Teaching': 'Explain your teaching methodology for engaging diverse learners. How do you assess student progress and adapt your approach?',
        'Legal': 'Describe your experience with legal research and case analysis. What is your approach to drafting complex legal documents?',
        'Customer Support': 'How do you troubleshoot complex technical issues? Describe your escalation process and how you ensure customer satisfaction.',
        'DevOps': 'Explain your experience with CI/CD pipelines. How do you implement infrastructure as code and ensure system reliability?',
        'Content Writing': 'Describe your research and writing process. How do you optimize content for SEO while maintaining quality and engagement?',
        'Java': 'Explain your experience with Java frameworks like Spring or Hibernate. How do you handle concurrency and optimize application performance?',
        'Node.js': 'Describe your experience building RESTful APIs with Node.js. How do you handle authentication, error handling, and scalability?',
        'Angular': 'Explain your approach to building large-scale Angular applications. How do you manage state and optimize performance?',
        'AWS': 'What AWS services have you worked with? Describe how you architect cloud solutions for scalability and cost optimization.',
        'SQL': 'Explain your experience writing complex SQL queries. How do you optimize database performance and handle large datasets?',
        'Machine Learning': 'Describe a machine learning project you worked on from problem definition to deployment. What challenges did you face?'
      };

      questions.push({
        id: qId++,
        question: techQuestions[primarySkill] || `What specific technical skills and tools related to ${primarySkill} have you worked with? Describe a complex problem you solved using these skills.`,
        difficulty: 'Medium',
        time: 180,
        type: 'technical'
      });
    }

    if (secondarySkill && secondarySkill !== primarySkill) {
      // Technical question 2 - Secondary skill
      questions.push({
        id: qId++,
        question: `Tell me about your hands-on experience with ${secondarySkill}. Can you describe a specific project or task where you applied this skill?`,
        difficulty: 'Medium',
        time: 150,
        type: 'technical'
      });
    }

    if (tertiarySkill && tertiarySkill !== primarySkill && tertiarySkill !== secondarySkill) {
      // Technical question 3 - Tertiary skill
      questions.push({
        id: qId++,
        question: `How have you used ${tertiarySkill} in your work? Give me an example of how it complemented your other skills.`,
        difficulty: 'Medium',
        time: 120,
        type: 'technical'
      });
    } else if (!secondarySkill && primarySkill) {
      // If only one skill detected, ask another deep technical question
      questions.push({
        id: qId++,
        question: `What are the biggest technical challenges you've faced while working with ${primarySkill}, and how did you overcome them?`,
        difficulty: 'Hard',
        time: 180,
        type: 'technical'
      });
    }

    // 5. PRACTICAL SCENARIO - Role-specific situational question
    const scenarioQuestions = {
      'SAP': 'A client requests a custom SAP report that needs data from multiple modules. Walk me through your approach to requirement gathering, design, and implementation.',
      'Salesforce': 'Your organization is hitting Salesforce governor limits in production. How would you diagnose and resolve this issue?',
      'React': 'Your React application is experiencing performance issues with slow rendering. How would you identify bottlenecks and optimize it?',
      'Data Science': 'Your machine learning model is performing well on training data but poorly on test data. What steps would you take to address this?',
      'Digital Marketing': 'Your paid ad campaign is getting high impressions but low conversions. How would you diagnose and improve it?',
      'UI/UX Design': 'User testing reveals that users are confused by a key feature. How would you redesign it while meeting business requirements?',
      'Accounting': 'You discover a significant discrepancy during month-end reconciliation. What is your step-by-step approach to investigating and resolving it?',
      'Project Management': 'Your project is running behind schedule and over budget. How would you get it back on track while managing stakeholder expectations?',
      'Sales': 'You are in the final stage of a large deal and the client raises a major pricing objection. How would you handle this situation?',
      'DevOps': 'Your production system experiences unexpected downtime. Walk me through your incident response and resolution process.'
    };

    questions.push({
      id: qId++,
      question: scenarioQuestions[primarySkill] || `Imagine you encounter a critical issue in your work as a ${detectedRole}. Walk me through your problem-solving approach step by step.`,
      difficulty: 'Hard',
      time: 180,
      type: 'scenario'
    });

    // 6. PROJECT/ACHIEVEMENT QUESTION - Focused on technical delivery
    questions.push({
      id: qId++,
      question: `Describe the most technically challenging or impactful project you've delivered as a ${detectedRole}. What was your specific contribution and what technologies did you use?`,
      difficulty: 'Hard',
      time: 180,
      type: 'achievement'
    });

    // 7. BEST PRACTICES & METHODOLOGY - Role-specific
    const methodologyQuestions = {
      'SAP': 'What best practices do you follow for SAP customization to ensure system upgradability and performance?',
      'React': 'What coding standards and best practices do you follow in React development? How do you ensure code quality?',
      'Data Science': 'How do you ensure reproducibility and maintainability in your data science projects?',
      'DevOps': 'What monitoring and alerting strategies do you implement to ensure system reliability?',
      'Project Management': 'How do you handle changing requirements and scope creep in projects?',
      'Accounting': 'What internal controls do you implement to ensure accuracy and prevent errors in financial processes?',
      'Digital Marketing': 'How do you stay updated with algorithm changes and platform updates across different marketing channels?'
    };

    if (experienceLevel === 'senior' || experienceLevel === 'mid') {
      questions.push({
        id: qId++,
        question: methodologyQuestions[primarySkill] || `What industry best practices and standards do you follow in your role as a ${detectedRole}?`,
        difficulty: 'Medium',
        time: 120,
        type: 'methodology'
      });
    }

    // 8. TOOLS & TECHNOLOGY - Specific tooling question
    questions.push({
      id: qId++,
      question: `What tools, software, and technologies do you use daily in your ${detectedRole} role? Which ones are you most proficient in?`,
      difficulty: 'Easy',
      time: 120,
      type: 'tools'
    });

    // 9. ONLY ONE BEHAVIORAL QUESTION - Kept minimal
    questions.push({
      id: qId++,
      question: 'Tell me about a time when you had to collaborate with cross-functional teams or handle a disagreement with a colleague. How did you handle it?',
      difficulty: 'Medium',
      time: 120,
      type: 'behavioral'
    });

    // 10. LEARNING & GROWTH - Only for junior/mid level
    if (experienceLevel === 'fresher' || experienceLevel === 'junior') {
      questions.push({
        id: qId++,
        question: `What emerging technologies or skills in the ${detectedRole} field are you currently learning or want to learn?`,
        difficulty: 'Easy',
        time: 90,
        type: 'learning'
      });
    } else if (experienceLevel === 'senior') {
      // Leadership/mentoring for senior roles
      questions.push({
        id: qId++,
        question: `As a senior ${detectedRole}, how do you share knowledge with your team and ensure technical excellence across the organization?`,
        difficulty: 'Medium',
        time: 120,
        type: 'leadership'
      });
    }

    // 11. CLOSING QUESTION - Why this role (keep it short and focused)
    questions.push({
      id: qId++,
      question: `What specifically interests you about this ${detectedRole} position, and what unique technical expertise can you bring to the role?`,
      difficulty: 'Easy',
      time: 90,
      type: 'closing'
    });

    return questions;
  };

  scoreAnswerWithAI = async (question, answer, difficulty) => {
    console.log('scoreAnswerWithAI fallback - using rule-based scoring');

    // Enhanced fallback scoring
    if (!answer || answer.trim().length < 10) {
      return {
        score: 0,
        feedback: 'No meaningful answer provided. Please try to answer the question in detail.'
      };
    }

    const maxScore = difficulty === 'Easy' ? 10 : difficulty === 'Medium' ? 20 : 30;

    // Calculate score based on multiple factors
    const wordCount = answer.split(/\s+/).filter(w => w.length > 0).length;
    const sentenceCount = answer.split(/[.!?]+/).filter(s => s.trim().length > 0).length;

    // Extract key terms from question
    const questionWords = question.toLowerCase()
      .split(/\s+/)
      .filter(w => w.length > 3 && !['what', 'when', 'where', 'which', 'would', 'could', 'should', 'about', 'your', 'yourself', 'tell', 'describe'].includes(w));

    // Check for relevant keywords
    const answerLower = answer.toLowerCase();
    const relevantKeywords = questionWords.filter(word => answerLower.includes(word)).length;
    const keywordScore = Math.min(relevantKeywords / Math.max(questionWords.length, 1), 1);

    // Length score with proper scaling
    let lengthScore;
    if (wordCount < 20) {
      lengthScore = wordCount / 20 * 0.5; // Up to 50% for very short
    } else if (wordCount < 50) {
      lengthScore = 0.5 + ((wordCount - 20) / 30) * 0.25; // 50-75%
    } else if (wordCount < 100) {
      lengthScore = 0.75 + ((wordCount - 50) / 50) * 0.2; // 75-95%
    } else {
      lengthScore = 0.95; // Cap at 95%
    }

    // Structure score
    const structureScore = Math.min(sentenceCount / 5, 1);

    // Technical/professional terms bonus
    const professionalTerms = ['experience', 'project', 'developed', 'implemented', 'designed', 'managed', 'achieved', 'improved', 'responsible', 'team', 'skills', 'technology', 'system', 'application', 'problem', 'solution', 'worked', 'created', 'built', 'led'];
    const professionalCount = professionalTerms.filter(term => answerLower.includes(term)).length;
    const professionalBonus = Math.min(professionalCount / 5, 0.25); // Up to 25% bonus

    // Calculate final score (weighted average)
    const rawScore = (
      keywordScore * 0.35 +      // 35% for relevance
      lengthScore * 0.35 +        // 35% for completeness
      structureScore * 0.15 +     // 15% for structure
      professionalBonus           // 15-25% bonus for professional content
    );

    let finalScore = Math.round(rawScore * maxScore);

    // Ensure minimum score for genuine attempts (at least 30% if answer has substance)
    if (wordCount >= 15 && finalScore < maxScore * 0.3) {
      finalScore = Math.round(maxScore * 0.3);
    }

    // Cap at max score
    finalScore = Math.min(finalScore, maxScore);

    // Generate contextual feedback
    const scorePercentage = (finalScore / maxScore) * 100;
    let feedback = '';

    if (scorePercentage >= 85) {
      feedback = 'Excellent answer! You demonstrated strong understanding with clear, detailed explanations.';
    } else if (scorePercentage >= 70) {
      feedback = 'Great answer! You covered the key points well. Adding more specific examples would make it even stronger.';
    } else if (scorePercentage >= 55) {
      feedback = 'Good effort! Your answer addresses the question but could benefit from more depth and specific examples.';
    } else if (scorePercentage >= 40) {
      feedback = 'Adequate response. Try to elaborate more and connect your answer directly to the question asked.';
    } else if (scorePercentage >= 20) {
      feedback = 'Basic answer provided. Focus on giving more detailed explanations and relevant examples.';
    } else {
      feedback = 'Brief answer. Please provide more comprehensive responses with specific details and examples.';
    }

    // Add specific tips based on what's missing
    const tips = [];
    if (wordCount < 30) tips.push('Try to speak for at least 30-40 words');
    if (relevantKeywords < questionWords.length * 0.5) tips.push('Make sure to directly address the question');
    if (professionalCount === 0) tips.push('Include specific examples from your experience');

    if (tips.length > 0) {
      feedback += ` Tips: ${tips.join('; ')}.`;
    }

    return {
      score: finalScore,
      feedback: feedback
    };
  };
}

const VideoInterviewPage = ({ candidate, onComplete, onBack }) => {
  const [stream, setStream] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [questions, setQuestions] = useState([]);
  const [timeRemaining, setTimeRemaining] = useState(null);
  const [transcript, setTranscript] = useState('');
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [status, setStatus] = useState('initializing');
  const [error, setError] = useState('');

  const videoRef = useRef(null);
  const voiceEngine = useRef(null);
  const speechEngine = useRef(null);
  const timerRef = useRef(null);
  const answersRef = useRef([]);
  const isProcessingRef = useRef(false);
  const hasInitialized = useRef(false);

  // ⭐ FIXED: Safe voice engine start
  const startRecording = useCallback(() => {
    if (!voiceEngine.current) {
      console.error('Voice engine not initialized');
      return false;
    }

    if (voiceEngine.current.isActive && voiceEngine.current.isActive()) {
      console.warn('⚠️ Already recording, skipping start');
      return true;
    }

    if (isRecording) {
      console.warn('⚠️ isRecording flag is true, skipping start');
      return true;
    }

    console.log('🎤 Starting voice recording...');
    const started = voiceEngine.current.start();

    if (started) {
      setIsRecording(true);
      console.log('✅ Recording started successfully');
      return true;
    } else {
      console.error('❌ Failed to start recording');
      return false;
    }
  }, [isRecording]);

  // ⭐ FIXED: Safe voice engine stop
  const stopRecording = useCallback(() => {
    if (!voiceEngine.current) return '';

    console.log('🛑 Stopping voice recording...');
    const finalTranscript = voiceEngine.current.stop();
    setIsRecording(false);

    console.log('✅ Recording stopped. Transcript:', finalTranscript);
    return finalTranscript || transcript;
  }, [transcript]);

  // Cleanup media and engines
  const cleanup = useCallback(() => {
    console.log('🧹 Cleaning up resources...');

    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    if (voiceEngine.current) {
      voiceEngine.current.abort?.();
      voiceEngine.current = null;
    }

    if (speechEngine.current) {
      speechEngine.current.stop();
      speechEngine.current = null;
    }

    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  }, [stream]);

  // Text-to-speech
  const speakText = useCallback(async (text) => {
    if (!speechEngine.current) return;

    if (isRecording) {
      stopRecording();
    }

    setIsAISpeaking(true);
    console.log('🗣️ AI Speaking:', text);

    try {
      await speechEngine.current.speak(text, {
        rate: 0.95,
        pitch: 1.1,
        volume: 1.0,
        onEnd: () => {
          console.log('✅ AI finished speaking');
          setIsAISpeaking(false);
        },
      });
    } catch (err) {
      console.error('Speech error:', err);
      setIsAISpeaking(false);
    }
  }, [isRecording, stopRecording]);

  // Complete interview
  const completeInterview = useCallback(async () => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    console.log('🎉 Completing interview...');
    setStatus('completed');

    const totalScore = answersRef.current.reduce((sum, ans) => sum + ans.score, 0);
    const maxScore = answersRef.current.reduce((sum, ans) => {
      const max = ans.difficulty === 'Easy' ? 10 : ans.difficulty === 'Medium' ? 20 : 30;
      return sum + max;
    }, 0);

    await speakText(`Interview complete! Your total score is ${totalScore} out of ${maxScore} points. Thank you for your time.`);

    setTimeout(() => {
      cleanup();
      onComplete({
        ...candidate,
        answers: answersRef.current,
        completed: true,
        completedAt: Date.now(),
        totalScore,
        maxScore,
        summary: `Total Score: ${totalScore}/${maxScore} points`,
      });
    }, 3000);
  }, [candidate, onComplete, speakText, cleanup]);

  // ⭐ CRITICAL FIX: Use ref instead of callback dependency
  const startQuestionRef = useRef();

  // ⭐ FIXED: Submit answer helper - NO startQuestion dependency
  const submitAnswerHelper = useCallback(async (questionIndex, finalTranscript, currentTimeRemaining) => {
    if (isProcessingRef.current) return;

    isProcessingRef.current = true;
    setStatus('evaluating');

    const question = questions[questionIndex];
    if (!question) {
      console.error('No question found for index:', questionIndex);
      isProcessingRef.current = false;
      return;
    }

    try {
      // Score the answer
      const result = await scoreAnswerWithAI(
        question.question,
        finalTranscript || '(No answer provided)',
        question.difficulty
      );

      const newAnswer = {
        questionId: question.id,
        question: question.question,
        answer: finalTranscript,
        score: result.score,
        feedback: result.feedback,
        difficulty: question.difficulty,
        timeUsed: question.time - (currentTimeRemaining || 0),
      };

      answersRef.current = [...answersRef.current, newAnswer];
      console.log('✅ Answer saved:', newAnswer);

      // Provide feedback
      const maxScore = question.difficulty === 'Easy' ? 10 : question.difficulty === 'Medium' ? 20 : 30;
      await speakText(`You scored ${result.score} out of ${maxScore} points. ${result.feedback}`);

      // Move to next question or complete
      if (questionIndex < questions.length - 1) {
        await speakText('Moving to the next question.');

        setTimeout(() => {
          isProcessingRef.current = false;
          // ⭐ FIX: Use ref instead of direct call
          if (startQuestionRef.current) {
            startQuestionRef.current(questionIndex + 1);
          }
        }, 2000);
      } else {
        isProcessingRef.current = false;
        completeInterview();
      }
    } catch (err) {
      console.error('Error submitting answer:', err);
      setError('Failed to evaluate answer. Please try again.');
      isProcessingRef.current = false;
    }
  }, [questions, speakText, completeInterview]);

  // ⭐ FIXED: Main submit answer function (now mostly for manual submission)
  const handleSubmitAnswer = useCallback(() => {
    if (isProcessingRef.current) {
      console.warn('⚠️ Already processing, skipping submit');
      return;
    }

    console.log('📝 Manual submit triggered...');

    // Stop recording and get transcript
    const finalTranscript = stopRecording();

    // Clear timer
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    submitAnswerHelper(currentQuestionIndex, finalTranscript, timeRemaining);
  }, [stopRecording, currentQuestionIndex, timeRemaining, submitAnswerHelper]);

  // ⭐ FIXED: Start a question with proper state management
  const startQuestion = useCallback((index) => {
    if (isProcessingRef.current && status === 'answering') {
      console.warn('⚠️ Still processing previous question');
      return;
    }

    const question = questions[index];
    if (!question) {
      console.error('No question found for index:', index);
      return;
    }

    console.log(`📋 Starting question ${index + 1}:`, question.question);

    setCurrentQuestionIndex(index);
    setTimeRemaining(question.time);
    setTranscript('');
    setStatus('asking');

    // Initialize voice engine if needed
    if (!voiceEngine.current) {
      voiceEngine.current = new VoiceEngine();
      voiceEngine.current.setCallbacks({
        onResult: (result) => {
          setTranscript(result.full);
        },
        onSilence: () => {
          console.log('🤫 Silence detected, auto-submitting...');
          // Use setTimeout to ensure state is updated
          setTimeout(() => {
            if (isRecording) {
              handleSubmitAnswer();
            }
          }, 100);
        },
        onError: (err) => {
          console.error('Voice recognition error:', err);
          setError(`Microphone error: ${err}`);
        },
      });
    }

    // ⭐ Enhanced question delivery
    let questionText = `Question ${index + 1}.`;

    if (question.type === 'introduction') {
      questionText += ' Let\'s start with an introduction.';
    } else if (question.type === 'closing') {
      questionText += ' This is our final question.';
    }

    questionText += ` ${question.question}. You have ${question.time} seconds to answer.`;

    // Speak the question
    speakText(questionText).then(() => {
      // Wait a moment after speaking, then start recording
      setTimeout(() => {
        setStatus('answering');

        const started = startRecording();

        if (started) {
          // Start timer
          if (timerRef.current) clearInterval(timerRef.current);

          // ⭐ CRITICAL FIX: Store timer in variable to access in cleanup
          let timeLeft = question.time;

          timerRef.current = setInterval(() => {
            timeLeft -= 1;
            setTimeRemaining(timeLeft);

            // ⭐ FIX: Direct check and submit when time expires
            if (timeLeft <= 0) {
              console.log('⏰ Time expired! Auto-submitting answer...');
              clearInterval(timerRef.current);
              timerRef.current = null;

              // Force submit immediately
              setTimeout(() => {
                const finalTranscript = stopRecording();
                submitAnswerHelper(index, finalTranscript, 0);
              }, 100);
            }
          }, 1000);
        } else {
          console.error('Failed to start recording');
          setError('Failed to start voice recognition. Please check microphone permissions.');
        }
      }, 1500);
    });
  }, [questions, status, speakText, startRecording, handleSubmitAnswer, isRecording, stopRecording, submitAnswerHelper]);

  // ⭐ CRITICAL: Store startQuestion in ref to avoid circular dependency
  useEffect(() => {
    startQuestionRef.current = startQuestion;
  }, [startQuestion]);

  // ⭐ FIXED: Initialize interview with proper error handling and prevent triple message
  const initializeInterview = useCallback(async () => {
    // ⭐ CRITICAL FIX: Prevent multiple initializations
    if (hasInitialized.current) {
      console.warn('⚠️ Already initialized, skipping...');
      return;
    }
    hasInitialized.current = true;

    try {
      console.log('🚀 Initializing video interview...');

      // Request camera and microphone
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1920, min: 1280 },
          height: { ideal: 1080, min: 720 },
          facingMode: 'user',
          frameRate: { ideal: 30, min: 24 },
          aspectRatio: 16/9,
          resizeMode: 'crop-and-scale'
        },
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          sampleRate: 48000,
          channelCount: 1
        }
      });

      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }

      // Initialize engines
      voiceEngine.current = new VoiceEngine();
      speechEngine.current = new SpeechSynthesisEngine();
      await speechEngine.current.initialize();

      console.log('✅ Media and engines initialized');

      // Generate questions
      setStatus('generating_questions');
      const qs = await generateInterviewQuestions(
        `Name: ${candidate?.name || 'Candidate'}\nEmail: ${candidate?.email || 'email@example.com'}\n${candidate?.resumeText || ''}`,
        'Full Stack Developer'
      );

      setQuestions(qs);
      setStatus('ready');
      console.log('✅ Generated', qs.length, 'questions');

      // Welcome message - THIS WILL NOW ONLY PLAY ONCE
      await speakText(
        'Hello! Welcome to your video interview. I\'m your AI interviewer today. We\'ll have a professional conversation about your experience and skills. Let\'s begin with an introduction.'
      );

      // Start first question
      setTimeout(() => {
        if (startQuestionRef.current) {
          startQuestionRef.current(0);
        }
      }, 2000);

    } catch (err) {
      console.error('Initialization error:', err);
      setError('Failed to access camera/microphone. Please grant permissions and refresh the page.');
      setStatus('error');
      // ⭐ Reset flag on error so user can retry
      hasInitialized.current = false;
    }
  }, [candidate?.name, candidate?.email, candidate?.resumeText, speakText]);

  // Initialize on mount
  useEffect(() => {
    initializeInterview();
    return () => {
